"""Tiny numeric helpers."""

from collections.abc import Sequence


def sum_inclusive(start: int, end: int) -> int:
    """Sum integers from ``start`` to ``end`` inclusive."""
    return sum(range(start, end))


def average(nums: Sequence[float]) -> float:
    if not nums:
        raise ValueError("cannot average an empty sequence")
    return sum(nums) / len(nums)


def is_even(n: int) -> bool:
    return n % 2 == 0

"""Sales-tax tables keyed by shop settings."""

from __future__ import annotations

from app import settings


class Nexus:
    def __init__(self, code: str, rate: float) -> None:
        self.code = code
        self.rate = rate

    def applies(self, code: str) -> bool:
        return self.code == code

    def amount(self, subtotal: float) -> float:
        return round(float(subtotal) * float(self.rate), 2)


_NEXUS: dict[str, Nexus] = {
    "home": Nexus("home", 0.0),
    "remote": Nexus("remote", 0.0),
}


def home_nexus() -> Nexus:
    return _NEXUS["home"]


def remote_nexus() -> Nexus:
    return _NEXUS["remote"]


def rate_for(code: str = "home") -> float:
    nexus = _NEXUS.get(code) or home_nexus()
    if nexus.rate:
        return nexus.rate
    return settings.tax_rate()


def tax_on(subtotal: float, code: str = "home") -> float:
    return round(float(subtotal) * rate_for(code), 2)


def away_levy(subtotal: float) -> float:
    return tax_on(subtotal, "remote")


def inclusive_total(subtotal: float, code: str = "home") -> float:
    return round(float(subtotal) + tax_on(subtotal, code), 2)


def exempt(subtotal: float) -> float:
    return round(float(subtotal), 2)


def set_nexus_rate(code: str, rate: float) -> None:
    if code not in _NEXUS:
        _NEXUS[code] = Nexus(code, rate)
    else:
        _NEXUS[code].rate = rate


def nexus_codes() -> list[str]:
    return sorted(_NEXUS)


def reset_store() -> None:
    _NEXUS.clear()
    _NEXUS["home"] = Nexus("home", 0.0)
    _NEXUS["remote"] = Nexus("remote", 0.0)

"""Quotes, tax, and coupons.

A coupon code should change the payable amount at most once. Checkout currently
does not call ``compute_checkout_total``.
"""

COUPONS = {
    "SAVE10": 0.10,
    "SAVE20": 0.20,
}


def quote_price(sku: str, qty: int, unit_price: float) -> float:
    """Unit quote helper; not used by ``orders.create_order``."""
    return round(unit_price * qty, 2)


def apply_tax(subtotal: float, tax_rate: float = 0.0) -> float:
    return round(subtotal * (1 + tax_rate), 2)


def apply_coupon(amount: float, code: str | None) -> float:
    if not code:
        return round(float(amount), 2)
    rate = COUPONS.get(code.upper(), 0.0)
    return round(float(amount) * (1.0 - rate), 2)


def compute_checkout_total(
    items: list[dict],
    coupon: str | None = None,
    tax_rate: float = 0.0,
) -> float:
    """One-shot subtotal → coupon → tax. Unused by the order service today."""
    subtotal = sum(float(item["price"]) * int(item.get("qty", 1)) for item in items)
    discounted = apply_coupon(subtotal, coupon)
    return apply_tax(discounted, tax_rate)

